SET NOCOUNT ON;
SET XACT_ABORT ON;
USE [master];
IF DB_ID(N'ibcmd_rs_05_online_b1') IS NULL THROW 57230, 'live activation database does not exist', 1;
IF (SELECT recovery_model FROM sys.databases WHERE name=N'ibcmd_rs_05_online_b1') NOT IN (1,2) THROW 57231, 'live activation requires FULL or BULK_LOGGED recovery', 1;
IF (SELECT state FROM sys.databases WHERE name=N'ibcmd_rs_05_online_b1') <> 0 THROW 57232, 'live activation requires an ONLINE database', 1;
IF EXISTS (SELECT 1 FROM sys.dm_os_file_exists(N'F:\ibcmd\lab\05\online\bak\ibcmd_rs_05_online_b1_tail6.trn') WHERE file_exists=1 OR file_is_a_directory=1) THROW 57233, 'tail-log output already exists or is a directory', 1;
USE [ibcmd_rs_05_online_b1];
SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
BEGIN TRY
BEGIN TRANSACTION;
DECLARE @LockResult int;
EXEC @LockResult = sys.sp_getapplock @Resource=N'ibcmd-rs:main-activation', @LockMode='Exclusive', @LockOwner='Transaction', @LockTimeout=0;
IF @LockResult < 0 THROW 57200, 'main activation application lock is busy', 1;
DECLARE @ExpectedStage TABLE (FileName nvarchar(4000) NOT NULL, PartNo int NOT NULL, DataSize bigint NOT NULL, Digest varbinary(32) NOT NULL, PRIMARY KEY(FileName,PartNo));
INSERT @ExpectedStage VALUES (N'313d9858-3995-4a4c-b2b0-15d2350417b4',0, 165,0x68173761147FEB4F08F70888C846710869E4B683FD5696550561E82ECAAA77FA);
INSERT @ExpectedStage VALUES (N'313d9858-3995-4a4c-b2b0-15d2350417b4.0',0, 702,0x9BAAEC275966E4241004F7CDE6973D83712EC3055112CB93BB9450A097833F75);
INSERT @ExpectedStage VALUES (N'root',0, 45,0xADFE2E91D2EFB05910281F6EFBB026ADFA876AA812D082C7F9E755028632A256);
INSERT @ExpectedStage VALUES (N'version',0, 28,0xEC6D68D22CDFA563A8FA7B32B6C827ABC9B84B1C0FEBC543EFC70E450459B795);
INSERT @ExpectedStage VALUES (N'versions',0, 344217,0x757BE871AA3E8687F9578CCFEA956FA96E96D33E4406321A8B575526E7A366D4);
DECLARE @ExpectedActive TABLE (FileName nvarchar(4000) NOT NULL, PartNo int NOT NULL, DataSize bigint NOT NULL, Digest varbinary(32) NOT NULL, PRIMARY KEY(FileName,PartNo));
INSERT @ExpectedActive VALUES (N'313d9858-3995-4a4c-b2b0-15d2350417b4',0, 165,0x68173761147FEB4F08F70888C846710869E4B683FD5696550561E82ECAAA77FA);
INSERT @ExpectedActive VALUES (N'313d9858-3995-4a4c-b2b0-15d2350417b4.0',0, 702,0x59732538028FA2B62DDA5B605AA3BACF6B6BFD2EC53121AE6277377A4ADFA459);
INSERT @ExpectedActive VALUES (N'root',0, 45,0xADFE2E91D2EFB05910281F6EFBB026ADFA876AA812D082C7F9E755028632A256);
INSERT @ExpectedActive VALUES (N'version',0, 28,0xEC6D68D22CDFA563A8FA7B32B6C827ABC9B84B1C0FEBC543EFC70E450459B795);
INSERT @ExpectedActive VALUES (N'versions',0, 344213,0xD253AF7D1DC270B053C4B1F470C116481F51EA542FBFA49291F4B076A9979CDA);
IF EXISTS (SELECT FileName,PartNo,CONVERT(bigint,DataSize),HASHBYTES('SHA2_256',BinaryData) FROM dbo.ConfigSave WITH (UPDLOCK,HOLDLOCK) EXCEPT SELECT FileName,PartNo,DataSize,Digest FROM @ExpectedStage) OR EXISTS (SELECT FileName,PartNo,DataSize,Digest FROM @ExpectedStage EXCEPT SELECT FileName,PartNo,CONVERT(bigint,DataSize),HASHBYTES('SHA2_256',BinaryData) FROM dbo.ConfigSave WITH (UPDLOCK,HOLDLOCK)) THROW 57201, 'ConfigSave exact snapshot drifted', 1;
IF EXISTS (SELECT E.FileName,E.PartNo FROM @ExpectedActive E LEFT JOIN dbo.Config T WITH (UPDLOCK,HOLDLOCK) ON T.FileName=E.FileName AND T.PartNo=E.PartNo AND CONVERT(bigint,T.DataSize)=E.DataSize AND HASHBYTES('SHA2_256',T.BinaryData)=E.Digest WHERE T.FileName IS NULL) THROW 57202, 'Config selected snapshot drifted', 1;
IF EXISTS (SELECT 1 FROM dbo.Config WITH (UPDLOCK,HOLDLOCK) WHERE FileName=N'DynamicallyUpdated') THROW 57203, 'unexpected Config.DynamicallyUpdated row', 1;
IF EXISTS (SELECT 1 FROM dbo.Params WITH (UPDLOCK,HOLDLOCK) WHERE FileName=N'DynamicallyUpdated') THROW 57204, 'unexpected Params.DynamicallyUpdated row', 1;
DELETE FROM dbo.Config WHERE FileName=N'313d9858-3995-4a4c-b2b0-15d2350417b4' AND PartNo=0;
INSERT dbo.Config (FileName,Creation,Modified,Attributes,DataSize,BinaryData,PartNo) SELECT FileName,Creation,Modified,Attributes,DataSize,BinaryData,PartNo FROM dbo.ConfigSave WHERE FileName=N'313d9858-3995-4a4c-b2b0-15d2350417b4' AND PartNo=0;
IF @@ROWCOUNT <> 1 THROW 57210, 'exclusive promotion source drifted', 1;
DELETE FROM dbo.Config WHERE FileName=N'313d9858-3995-4a4c-b2b0-15d2350417b4.0' AND PartNo=0;
INSERT dbo.Config (FileName,Creation,Modified,Attributes,DataSize,BinaryData,PartNo) SELECT FileName,Creation,Modified,Attributes,DataSize,BinaryData,PartNo FROM dbo.ConfigSave WHERE FileName=N'313d9858-3995-4a4c-b2b0-15d2350417b4.0' AND PartNo=0;
IF @@ROWCOUNT <> 1 THROW 57210, 'exclusive promotion source drifted', 1;
DELETE FROM dbo.Config WHERE FileName=N'root' AND PartNo=0;
INSERT dbo.Config (FileName,Creation,Modified,Attributes,DataSize,BinaryData,PartNo) SELECT FileName,Creation,Modified,Attributes,DataSize,BinaryData,PartNo FROM dbo.ConfigSave WHERE FileName=N'root' AND PartNo=0;
IF @@ROWCOUNT <> 1 THROW 57210, 'exclusive promotion source drifted', 1;
DELETE FROM dbo.Config WHERE FileName=N'version' AND PartNo=0;
INSERT dbo.Config (FileName,Creation,Modified,Attributes,DataSize,BinaryData,PartNo) SELECT FileName,Creation,Modified,Attributes,DataSize,BinaryData,PartNo FROM dbo.ConfigSave WHERE FileName=N'version' AND PartNo=0;
IF @@ROWCOUNT <> 1 THROW 57210, 'exclusive promotion source drifted', 1;
DELETE FROM dbo.Config WHERE FileName=N'versions' AND PartNo=0;
INSERT dbo.Config (FileName,Creation,Modified,Attributes,DataSize,BinaryData,PartNo) SELECT FileName,Creation,Modified,Attributes,DataSize,BinaryData,PartNo FROM dbo.ConfigSave WHERE FileName=N'versions' AND PartNo=0;
IF @@ROWCOUNT <> 1 THROW 57210, 'exclusive promotion source drifted', 1;
DELETE FROM dbo.Config WHERE FileName=N'DynamicallyUpdated';
IF @@ROWCOUNT <> 0 THROW 57215, 'Config.DynamicallyUpdated cleanup drifted', 1;
DELETE FROM dbo.Params WHERE FileName=N'DynamicallyUpdated';
IF @@ROWCOUNT <> 0 THROW 57216, 'Params.DynamicallyUpdated cleanup drifted', 1;
DELETE FROM dbo.ConfigSave;
IF @@ROWCOUNT <> 5 THROW 57220, 'ConfigSave cleanup drifted', 1;
DECLARE @ExpectedPublished TABLE (FileName nvarchar(4000) NOT NULL, PartNo int NOT NULL, DataSize bigint NOT NULL, Digest varbinary(32) NOT NULL, PRIMARY KEY(FileName,PartNo));
INSERT @ExpectedPublished VALUES (N'313d9858-3995-4a4c-b2b0-15d2350417b4',0, 165,0x68173761147FEB4F08F70888C846710869E4B683FD5696550561E82ECAAA77FA);
INSERT @ExpectedPublished VALUES (N'313d9858-3995-4a4c-b2b0-15d2350417b4.0',0, 702,0x9BAAEC275966E4241004F7CDE6973D83712EC3055112CB93BB9450A097833F75);
INSERT @ExpectedPublished VALUES (N'root',0, 45,0xADFE2E91D2EFB05910281F6EFBB026ADFA876AA812D082C7F9E755028632A256);
INSERT @ExpectedPublished VALUES (N'version',0, 28,0xEC6D68D22CDFA563A8FA7B32B6C827ABC9B84B1C0FEBC543EFC70E450459B795);
INSERT @ExpectedPublished VALUES (N'versions',0, 344217,0x757BE871AA3E8687F9578CCFEA956FA96E96D33E4406321A8B575526E7A366D4);
IF EXISTS (SELECT E.FileName,E.PartNo FROM @ExpectedPublished E LEFT JOIN dbo.Config T WITH (UPDLOCK,HOLDLOCK) ON T.FileName=E.FileName AND T.PartNo=E.PartNo AND CONVERT(bigint,T.DataSize)=E.DataSize AND HASHBYTES('SHA2_256',T.BinaryData)=E.Digest WHERE T.FileName IS NULL) THROW 57222, 'Config selected snapshot drifted', 1;
IF EXISTS (SELECT 1 FROM dbo.Config WHERE FileName=N'DynamicallyUpdated') THROW 57225, 'Config.DynamicallyUpdated cleanup postcondition failed', 1;
IF EXISTS (SELECT 1 FROM dbo.Params WHERE FileName=N'DynamicallyUpdated') THROW 57226, 'Params.DynamicallyUpdated cleanup postcondition failed', 1;
IF EXISTS (SELECT 1 FROM dbo.ConfigSave) THROW 57221, 'ConfigSave postcondition failed', 1;
COMMIT TRANSACTION;
END TRY
BEGIN CATCH
IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
THROW;
END CATCH;
DECLARE @LiveExpected1cConnections int=(SELECT COUNT(*) FROM sys.dm_exec_sessions WHERE is_user_process=1 AND database_id=DB_ID(N'ibcmd_rs_05_online_b1') AND program_name=N'1CV83 Server');
CHECKPOINT;
USE [master];
BEGIN TRY
ALTER DATABASE [ibcmd_rs_05_online_b1] SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
BACKUP LOG [ibcmd_rs_05_online_b1] TO DISK=N'F:\ibcmd\lab\05\online\bak\ibcmd_rs_05_online_b1_tail6.trn' WITH NORECOVERY, INIT, COMPRESSION, CHECKSUM;
RESTORE DATABASE [ibcmd_rs_05_online_b1] WITH RECOVERY;
ALTER DATABASE [ibcmd_rs_05_online_b1] SET MULTI_USER;
DECLARE @LiveReconnectDeadline datetime2(3)=DATEADD(millisecond,4000,SYSUTCDATETIME()), @LiveStableSince datetime2(3)=NULL, @LiveObserved1cConnections int=0;
WHILE @LiveExpected1cConnections > 0 AND SYSUTCDATETIME() < @LiveReconnectDeadline BEGIN SELECT @LiveObserved1cConnections=COUNT(*) FROM sys.dm_exec_sessions WHERE is_user_process=1 AND database_id=DB_ID(N'ibcmd_rs_05_online_b1') AND program_name=N'1CV83 Server'; IF @LiveObserved1cConnections >= @LiveExpected1cConnections BEGIN IF @LiveStableSince IS NULL SET @LiveStableSince=SYSUTCDATETIME(); IF DATEDIFF(millisecond,@LiveStableSince,SYSUTCDATETIME()) >= 500 BREAK; END ELSE SET @LiveStableSince=NULL; WAITFOR DELAY '00:00:00.100'; END;
IF @LiveExpected1cConnections > 0 AND (@LiveObserved1cConnections < @LiveExpected1cConnections OR @LiveStableSince IS NULL OR DATEDIFF(millisecond,@LiveStableSince,SYSUTCDATETIME()) < 500) THROW 57234, '1C SQL connections did not recover before the live activation deadline; database is online and the second recovery was not started', 1;
ALTER DATABASE [ibcmd_rs_05_online_b1] SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
BACKUP LOG [ibcmd_rs_05_online_b1] TO DISK=N'F:\ibcmd\lab\05\online\bak\ibcmd_rs_05_online_b1_tail6.trn' WITH NORECOVERY, NOINIT, COMPRESSION, CHECKSUM;
RESTORE DATABASE [ibcmd_rs_05_online_b1] WITH RECOVERY;
ALTER DATABASE [ibcmd_rs_05_online_b1] SET MULTI_USER;
END TRY
BEGIN CATCH
IF DB_ID(N'ibcmd_rs_05_online_b1') IS NOT NULL AND DATABASEPROPERTYEX(N'ibcmd_rs_05_online_b1','Status') <> N'RESTORING' ALTER DATABASE [ibcmd_rs_05_online_b1] SET MULTI_USER;
IF DB_ID(N'ibcmd_rs_05_online_b1') IS NOT NULL AND DATABASEPROPERTYEX(N'ibcmd_rs_05_online_b1','Status') = N'RESTORING' BEGIN DECLARE @LiveRecoveryMessage nvarchar(2048)=N'live activation left database restoring; run RESTORE DATABASE [ibcmd_rs_05_online_b1] WITH RECOVERY; original error: '+ERROR_MESSAGE(); THROW 57250,@LiveRecoveryMessage,1; END;
THROW;
END CATCH;
